// Gemini Vision Request bauen aus Telegram-Foto
const item = $input.first();
const binaryKey = Object.keys(item.binary || {})[0];
if (!binaryKey) {
  throw new Error('Kein Foto im Telegram-Update gefunden.');
}
const bin = item.binary[binaryKey];
const chatId = item.json.message.chat.id;

const schema = {
  type: 'object',
  properties: {
    items: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          grams: { type: 'number' },
          kcal: { type: 'number' },
          protein: { type: 'number' },
          carbs: { type: 'number' },
          fat: { type: 'number' }
        },
        required: ['name', 'grams', 'kcal', 'protein', 'carbs', 'fat']
      }
    },
    summary: { type: 'string' }
  },
  required: ['items', 'summary']
};

return [{
  json: {
    chatId,
    body: {
      system_instruction: {
        parts: [{ text: 'Du analysierst Fotos von Mahlzeiten fuer einen Kalorientracking-Bot. Schaetze pro sichtbarem Lebensmittel: Name und Portionsgroesse in Gramm (anhand visueller Hinweise wie Tellergroesse, Besteck), und Naehrwerte fuer DIESE Portion (kcal, Eiweiss, KH, Fett in g). Sei realistisch und konservativ. Antworte auf Deutsch.' }]
      },
      contents: [{
        role: 'user',
        parts: [
          { inline_data: { mime_type: bin.mimeType || 'image/jpeg', data: bin.data } },
          { text: 'Analysiere diese Mahlzeit.' }
        ]
      }],
      generationConfig: {
        responseMimeType: 'application/json',
        responseSchema: schema
      }
    }
  }
}];

// Gemini Antwort parsen, Reply + Rows bauen
const chatId = $('Foto: Body bauen').first().json.chatId;
const resp = $input.first().json;
const text = resp.candidates?.[0]?.content?.parts?.[0]?.text;
if (!text) {
  throw new Error('Keine Text-Antwort von Gemini: ' + JSON.stringify(resp).slice(0, 500));
}
const parsed = JSON.parse(text);

const now = new Date();
const pad = n => String(n).padStart(2, '0');
const datum = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;
const zeit = `${pad(now.getHours())}:${pad(now.getMinutes())}`;

const rows = parsed.items.map(it => ({
  Datum: datum,
  Zeit: zeit,
  Mahlzeit: it.name,
  'Menge (g)': Math.round(it.grams * 10) / 10,
  kcal: Math.round(it.kcal),
  'Eiweiß (g)': Math.round(it.protein * 10) / 10,
  'KH (g)': Math.round(it.carbs * 10) / 10,
  'Fett (g)': Math.round(it.fat * 10) / 10,
  Quelle: 'KI-Foto',
  Notiz: ''
}));

const totalKcal = parsed.items.reduce((s, x) => s + x.kcal, 0);
const totalP = parsed.items.reduce((s, x) => s + x.protein, 0);
const totalC = parsed.items.reduce((s, x) => s + x.carbs, 0);
const totalF = parsed.items.reduce((s, x) => s + x.fat, 0);

const lines = parsed.items.map(it =>
  `• ${it.name} (${Math.round(it.grams)}g): ${Math.round(it.kcal)} kcal`
);
const replyText = `📷 <b>Erkannt & geloggt:</b>\n${lines.join('\n')}\n\n<b>Σ ${Math.round(totalKcal)} kcal</b> (P ${Math.round(totalP)} / KH ${Math.round(totalC)} / F ${Math.round(totalF)})`;

return [{ json: { chatId, rows, replyText } }];

// OFF Antwort verarbeiten, default 100g loggen
const trigger = $('Telegram Trigger').first().json;
const chatId = trigger.message.chat.id;
const ean = (trigger.message.text || '').trim();
const data = $input.first().json;

if (data.status !== 1 || !data.product) {
  return [{ json: {
    chatId,
    rows: [],
    replyText: `📦 EAN <code>${ean}</code> nicht in Open Food Facts gefunden.\nSchick mir stattdessen eine Beschreibung (z.B. <i>'Skyr Natur 200g'</i>).`
  }}];
}

const p = data.product;
const n = p.nutriments || {};
let kcal100 = n['energy-kcal_100g'];
if (kcal100 == null) {
  const kj = n.energy_100g || n['energy-kj_100g'];
  if (kj != null) kcal100 = kj / 4.184;
}
if (kcal100 == null) {
  return [{ json: {
    chatId,
    rows: [],
    replyText: `📦 EAN <code>${ean}</code>: Naehrwerte fehlen in Open Food Facts.`
  }}];
}

const grams = 100;  // default
const factor = grams / 100;
const name = p.product_name_de || p.product_name || 'Unbekanntes Produkt';
const brand = (p.brands || '').split(',')[0].trim();
const displayName = brand ? `${brand} ${name}`.trim() : name;

const protein = (n.proteins_100g || 0) * factor;
const carbs = (n.carbohydrates_100g || 0) * factor;
const fat = (n.fat_100g || 0) * factor;
const kcal = kcal100 * factor;

const now = new Date();
const pad = x => String(x).padStart(2, '0');
const datum = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;
const zeit = `${pad(now.getHours())}:${pad(now.getMinutes())}`;

const rows = [{
  Datum: datum,
  Zeit: zeit,
  Mahlzeit: displayName,
  'Menge (g)': grams,
  kcal: Math.round(kcal),
  'Eiweiß (g)': Math.round(protein * 10) / 10,
  'KH (g)': Math.round(carbs * 10) / 10,
  'Fett (g)': Math.round(fat * 10) / 10,
  Quelle: 'OFF-Barcode',
  Notiz: `EAN ${ean}`
}];

const replyText = `📦 <b>${displayName}</b>\n${grams}g geloggt: ${Math.round(kcal)} kcal (P ${Math.round(protein)} / KH ${Math.round(carbs)} / F ${Math.round(fat)})\n\n<i>Andere Menge? Schick z.B. "${displayName} 200g" als Text.</i>`;

return [{ json: { chatId, rows, replyText } }];

// Gemini Text Request bauen
const trigger = $('Telegram Trigger').first().json;
const chatId = trigger.message.chat.id;
const userText = trigger.message.text || '';

const schema = {
  type: 'object',
  properties: {
    items: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          grams: { type: 'number' },
          kcal: { type: 'number' },
          protein: { type: 'number' },
          carbs: { type: 'number' },
          fat: { type: 'number' }
        },
        required: ['name', 'grams', 'kcal', 'protein', 'carbs', 'fat']
      }
    },
    summary: { type: 'string' }
  },
  required: ['items', 'summary']
};

return [{
  json: {
    chatId,
    body: {
      system_instruction: {
        parts: [{ text: 'Du bist ein praeziser Ernaehrungs-Parser. Der User schickt auf Deutsch was er gegessen hat. Zerlege es in einzelne Lebensmittel und schaetze fuer jedes: Name, Portionsgroesse in Gramm, und Naehrwerte fuer DIESE Portion (kcal, Eiweiss, KH, Fett in g). Wenn keine Menge angegeben ist, nimm typische Portionen an (z.B. 1 Ei = 60g). Sei realistisch.' }]
      },
      contents: [{
        role: 'user',
        parts: [{ text: `Was ich gegessen habe: ${userText}` }]
      }],
      generationConfig: {
        responseMimeType: 'application/json',
        responseSchema: schema
      }
    }
  }
}];

// Gemini Text-Antwort parsen, Reply + Rows bauen
const chatId = $('Text: Body bauen').first().json.chatId;
const resp = $input.first().json;
const text = resp.candidates?.[0]?.content?.parts?.[0]?.text;
if (!text) {
  throw new Error('Keine Text-Antwort von Gemini: ' + JSON.stringify(resp).slice(0, 500));
}
const parsed = JSON.parse(text);

const now = new Date();
const pad = x => String(x).padStart(2, '0');
const datum = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;
const zeit = `${pad(now.getHours())}:${pad(now.getMinutes())}`;

const rows = parsed.items.map(it => ({
  Datum: datum,
  Zeit: zeit,
  Mahlzeit: it.name,
  'Menge (g)': Math.round(it.grams * 10) / 10,
  kcal: Math.round(it.kcal),
  'Eiweiß (g)': Math.round(it.protein * 10) / 10,
  'KH (g)': Math.round(it.carbs * 10) / 10,
  'Fett (g)': Math.round(it.fat * 10) / 10,
  Quelle: 'KI-Schätzung',
  Notiz: ''
}));

const totalKcal = parsed.items.reduce((s, x) => s + x.kcal, 0);
const totalP = parsed.items.reduce((s, x) => s + x.protein, 0);
const totalC = parsed.items.reduce((s, x) => s + x.carbs, 0);
const totalF = parsed.items.reduce((s, x) => s + x.fat, 0);

const lines = parsed.items.map(it =>
  `• ${it.name} (${Math.round(it.grams)}g): ${Math.round(it.kcal)} kcal`
);
const replyText = `📝 <b>Geloggt:</b>\n${lines.join('\n')}\n\n<b>Σ ${Math.round(totalKcal)} kcal</b> (P ${Math.round(totalP)} / KH ${Math.round(totalC)} / F ${Math.round(totalF)})`;

return [{ json: { chatId, rows, replyText } }];

// Aus einem Item mit rows-Array N Items machen (eins pro Sheet-Zeile)
const src = $input.first().json;
if (!src.rows || src.rows.length === 0) {
  return [];
}
return src.rows.map(row => ({ json: row }));
